# owner: platform
import unittest
from hourglass.timesheet import timesheet_rows
from hourglass.models import Shift, Span
from hourglass.errors import ProjectError


def shift(worker, day, start, end):
    return Shift(worker, day, Span(start, end))


class TimesheetRowsTests(unittest.TestCase):
    def test_busiest_first(self):
        rows = timesheet_rows([
            shift("Ana", "mon", 540, 600),
            shift("Brisa", "mon", 540, 840),
            shift("Brisa", "tue", 540, 630)
        ])
        self.assertEqual(len(rows), 2)
        self.assertTrue(rows[0].startswith("Brisa"))

    def test_row_text(self):
        rows = timesheet_rows([
            shift("Brisa", "mon", 540, 840),
            shift("Brisa", "tue", 540, 630)
        ])
        self.assertEqual(
            rows, ["Brisa: 2 shifts, 6.5 hours"]
        )

    def test_single_shift_wording(self):
        rows = timesheet_rows([shift("Ana", "mon", 0, 20)])
        self.assertEqual(rows, ["Ana: 1 shift, 0.3 hours"])

    def test_empty_list(self):
        with self.assertRaises(ProjectError):
            timesheet_rows([])

    def test_blank_worker(self):
        with self.assertRaises(ProjectError):
            timesheet_rows([shift("  ", "mon", 0, 60)])


if __name__ == "__main__":
    unittest.main()
